import {createApi} from './focus-api.mjs';
export function mountAutomation(root,state,{backend=false}={}){
 if(backend&&!state&&root.querySelector('.desk-heading h1')?.textContent==='Know what’s connected.'){
  const api=createApi();Promise.all([api('autopilot'),api('state')]).then(([settings,session])=>{if(root.querySelector('.desk-heading h1')?.textContent!=='Know what’s connected.')return;root.querySelector('.autopilot-panel')?.remove();mountAutopilot(root,settings,{backend,operator:session.operator===true,api,onUpdate:result=>{root.querySelector('.autopilot-panel')?.remove();mountAutopilot(root,result,{backend,operator:true,api,onUpdate:()=>location.reload()});}});}).catch(()=>{});
  return;
 }
 if(!backend||!state)return;
 const target=root.querySelector('.sheet-body');if(!target)return;
 const a=state.automation;
 const card=document.createElement('section');card.className='automation-card';card.setAttribute('aria-label','Automation status');
 const eyebrow=document.createElement('span');eyebrow.className='eyebrow';eyebrow.textContent='AUTOMATION TRAIL';card.append(eyebrow);
 const title=document.createElement('h2');title.textContent=a?.status==='verified-existing'?'Access returned without a repair':a?.status==='verified'?'Access restored and independently verified':a?.status==='verification-pending'?'Access found; verification continues':a?.status==='repairing'?'Policy-approved repair is running':a?.status==='investigating'?'Specialists are reviewing the evidence':a?.status==='awaiting-merchant'?'Review ready for your decision':a?.status==='needs-attention'?'Automatic recovery needs attention':state.monitor?.status==='waiting'?'Watching the delivery window':state.monitor?.status==='attention'?'Missing access detected':'Watching payment and access';card.append(title);
 const detail=document.createElement('p');detail.textContent=a?.status==='verified-existing'?'The course system restored access on its own. PayTrace checked the current PayPal payment, enrollment, and protected lesson with zero grant writes. Ask the customer to confirm it works.':a?.status==='verified'?'The current payment, enrollment, and protected lesson checks agree. Customer confirmation is still separate.':a?.status==='verification-pending'?'PayTrace will retry fresh reads only. It will not apply another grant.':a?.status==='repairing'?'The exact preview passed your sandbox policy. The grant and verification are in progress.':a?.status==='investigating'?'PayPal and course records are being checked. No access change is authorized.':a?.status==='awaiting-merchant'?'The evidence review is complete. This case requires your decision.':a?.status==='needs-attention'?'The automated step stopped safely. Review current evidence before any further change.':state.monitor?.status==='waiting'?'The purchase is still inside its delivery window. We will check again automatically.':state.monitor?.status==='attention'?'The payment is complete and access is missing. Review the evidence to decide what happens next.':'PayTrace checks known purchases for missing digital access.';card.append(detail);
 const steps=document.createElement('div');steps.className='automation-steps';for(const [label,complete] of [['Payment confirmed',state.capture?.status==='COMPLETED'],['Access status checked',!!state.monitor?.checkedAt],['Evidence reviewed',!!state.review],[a?.status==='verified-existing'?'No grant needed':state.approval?.mode==='policy'?'Merchant policy':'Merchant approval',a?.status==='verified-existing'||!!state.approval],['Lesson verified',state.phase==='verified'&&state.proof?.passed]]){const step=document.createElement('span');step.className=complete?'done':'';step.textContent=(complete?'✓ ':'○ ')+label;steps.append(step);}card.append(steps);
 target.prepend(card);
}

export function mountAutopilot(root,settings,{backend=false,operator=false,api,onUpdate}={}){
 if(!backend||!settings)return;
 const policy=settings.policy,ready=settings.ready;
 const card=document.createElement('section');card.className='autopilot-panel surface';card.setAttribute('aria-label','Automatic recovery policy');
 card.innerHTML=`<span class="eyebrow">AUTOMATIC RECOVERY · SANDBOX</span><div class="autopilot-heading"><div><h2>Let routine access issues resolve themselves.</h2><p>After the four specialists agree, PayTrace can preview one narrow grant, check it against your policy, apply it once, and verify the purchased lesson. Anything uncertain stays in your queue.</p></div><span class="autopilot-state ${policy.enabled?'on':''}">${policy.enabled?'Policy on':'Policy off'}</span></div><div class="autopilot-guardrails"><span>PayPal sandbox only</span><span>The Light & Story Workshop only</span><span>Exact learner and capture match</span><span>No refunds or account transfers</span><span>Read-only verification retries</span></div><form class="autopilot-form"><label>Maximum purchase amount <span>USD</span><input name="amount" type="number" min="1" max="500" step="1" value="${policy.maxAmountCents/100}" required></label><label>Daily recovery limit <span>cases</span><input name="dailyLimit" type="number" min="1" max="10" step="1" value="${policy.dailyLimit}" required></label><label class="autopilot-consent"><input name="enabled" type="checkbox" ${policy.enabled?'checked':''}><span>I authorize PayTrace to apply eligible sandbox access grants within these limits.</span></label><button class="button primary" type="submit" ${!operator?'disabled':''}>Save recovery policy</button></form><p class="autopilot-note">${!operator?'Unlock the operator session in the checkout and setup desk to change this policy.':!ready?'Connect PayPal sandbox, the course service, and AI before enabling automatic recovery. You can save the policy as off.':'Changes take effect for future checks. Disable this policy at any time.'}</p><p class="autopilot-feedback" role="status"></p>`;
 root.append(card);
 const form=card.querySelector('form');form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button'),feedback=card.querySelector('.autopilot-feedback'),enabled=form.elements.enabled.checked;button.disabled=true;feedback.textContent='Saving policy…';try{const result=await api('autopilot',{enabled,maxAmountCents:Math.round(Number(form.elements.amount.value)*100),dailyLimit:Number(form.elements.dailyLimit.value)});onUpdate(result);feedback.textContent='Policy saved.';}catch(e){feedback.textContent=e.message||'Policy could not be saved.';button.disabled=false;}});
}
